const compiled = babel.transformSync(mutated, {filename}).code;
const mod = new Module(filename, module);
mod.filename = filename;
mod.paths = Module._nodeModulePaths(path.dirname(filename));
mod._compile(compiled, filename);
const BrokenGraphQLError = mod.exports.GraphQLError;
const GraphQLError = require(filename).GraphQLError;
