  });
  it('typed Error with deleted stack retains fallback coverage', function () {
    const original = new Error('original');
    delete original.stack;
    const e = new GraphQLError('msg', null, null, null, null, original);
    assert.strictEqual(typeof e.stack, 'string');
    const broken = new BrokenGraphQLError('msg', null, null, null, null, original);
    assert.strictEqual(broken.stack, undefined);
  });
});
